    raise SystemExit('Use Python 3.12 or newer. Example: PYTHON_BIN=python3.12 bash build_clearauth.sh')
if sys.version_info < (3,11):
    raise SystemExit('Use Python 3.11 or newer. Example: PYTHON_BIN=python3.11 bash build_clearauth.sh')
